<app-card heading="Feature 110" disableTooltip>
  <app-pill hideHint label='Plain'/>
  <app-pill  variant="success"  [hideHint]='!isActive'  label="Active"/>
  <app-pill [hideHint]="count > 3" [label]="title" variant="info" />
  <app-pill [variant]="isActive ? 'success' : 'warning'" label="Multi-line" [hideHint]="isActive"></app-pill>
  @if (isActive) {
